import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard', { cache: 'no-store' })
  if (!res.ok) throw new Error('Failed to load dashboard data')
  return res.json()
}

async function DashboardContent() {
  const data = await getDashboardData()

  return (
    <>
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </>
  )
}

export function DashboardSkeleton() {
  return (
    <div role="status" aria-label="Loading dashboard data">
      <div className="grid grid-cols-2 gap-4">
        <div className="card">
          <h2>Total Revenue</h2>
          <p>Loading...</p>
        </div>
        <div className="card">
          <h2>Total Invoices</h2>
          <p>Loading...</p>
        </div>
      </div>
      <div className="chart">
        <h2>Revenue</h2>
        <p>Loading...</p>
      </div>
      <div className="invoices">
        <h2>Latest Invoices</h2>
        <p>Loading...</p>
      </div>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<DashboardSkeleton />}>
        <DashboardContent />
      </Suspense>
    </main>
  )
}

